SELECT

FROM t_registration

    1 = 1
    AND patient_id = #{patientId}
    AND doctor_code = #{doctorCode}
    AND dept_code = #{deptCode}
    AND work_date = #{workDate}
    AND status = #{status}

ORDER BY work_date DESC, queue_no ASC, id DESC

SELECT COUNT(1) FROM t_registration
WHERE patient_id = #{patientId}
AND schedule_id = #{scheduleId}
AND status IN (0, 1, 2)

SELECT status AS status, COUNT(1) AS total FROM t_registration
AND work_date = #{workDate}
GROUP BY status
